import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {ReentrancyGuardTransientUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardTransientUpgradeable.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {NoncesUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/NoncesUpgradeable.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
import {CryptoartNFT} from "./CryptoartNFT.sol";
import {Error} from "./libraries/Error.sol";

/**
 * @title CryptoartVault
 * @notice Secure NFT vault with secret-protected retrieval using commit-reveal pattern
 * @dev Integrates with CryptoartNFT to manage pairing state atomically during unlock
 */
contract CryptoartVault is
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardTransientUpgradeable,
    NoncesUpgradeable,
    IERC721Receiver
{
    // ==========================================================================
    // Enums
    // ==========================================================================

    enum LockStatus {
        NONE, // No lock exists
        AUTHORIZED, // Lock authorized, waiting for NFT deposit
        LOCKED // NFT deposited and locked
    }

    // ==========================================================================
    // Constants
    // ==========================================================================

    /// @notice Initial commit fee
    uint256 public constant INITIAL_COMMIT_FEE = 0.005 ether;
    /// @notice Initial minimum delay between commit and reveal (10 minutes)
    uint256 public constant INITIAL_REVEAL_DELAY = 600;
    /// @notice Initial maximum time before commit expires (24 hours)
    uint256 public constant INITIAL_COMMIT_TIMEOUT = 24 hours;
    /// @notice Initial lockup period
    uint256 public constant INITIAL_LOCKUP_PERIOD = 150 days;

    // ==========================================================================
    // State Variables
    // ==========================================================================

    address public authoritySigner;
    CryptoartNFT public cryptoartNFT;

    /// @notice Fee required to commit an unlock (slow path only)
    uint256 public commitFee;
    /// @notice Minimum delay between commit and reveal (slow path only)
    uint256 public revealDelay;
    /// @notice Maximum time before commit expires (slow path only)
    uint256 public commitTimeout;
    /// @notice Lockup period before NFT can be unlocked by user
    uint256 public lockupPeriod;

    mapping(uint256 tokenId => LockStatus) public lockStatus;
    mapping(uint256 tokenId => bytes32 secretHash) public secretHashes;

    // Variable gap in case new variables are added on subsequent upgrades
    uint256[50] private __gap;

    // ==========================================================================
    // Structs
    // ==========================================================================

    /// @notice Commit data for slow path unlock
    struct UnlockCommit {
        bytes32 commitHash; // keccak256(abi.encodePacked(secret, recipient, salt))
        address committer; // Who committed (prevents frontrunning)
        uint256 timestamp; // When commit happened
        uint256 feePaid; // fee to prevent Denial-of-service
    }

    /// @notice Unlock commits per token ID (only for slow path)
    mapping(uint256 tokenId => UnlockCommit) public unlockCommits;

    /// @notice Timestamp when each NFT was locked (for 90-day lockup period)
    mapping(uint256 tokenId => uint256 lockedAtTimestamp) public lockTimestamps;

    // ==========================================================================
    // Events
    // ==========================================================================

    event NFTLocked(uint256 indexed tokenId);
    event LockCanceled(uint256 indexed tokenId, address indexed canceledBy);
    event NFTDeposited(
        uint256 indexed tokenId,
        address indexed from,
        address indexed operator
    );
    event NFTUnlocked(uint256 indexed tokenId, address indexed recipient);
    event UnlockCommitted(
        uint256 indexed tokenId,
        address indexed committer,
        bytes32 commitHash
    );
    event CommitCanceled(uint256 indexed tokenId, address indexed committer);
    event LockupPeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
    event NFTUnlockedFallback(
        uint256 indexed tokenId,
        address indexed recipient
    );
    event EmergencyUnlockAndRetrieval(
        uint256 indexed tokenId,
        address indexed recipient,
        address indexed owner
    );
    event AuthoritySignerUpdated(
        address indexed oldSigner,
        address indexed newSigner
    );
    event CommitFeeUpdated(uint256 oldFee, uint256 newFee);
    event RevealDelayUpdated(uint256 oldDelay, uint256 newDelay);
    event CommitTimeoutUpdated(uint256 oldTimeout, uint256 newTimeout);
    event FeesWithdrawn(address indexed recipient, uint256 amount);

    // ==========================================================================
    // Initialization
    // ==========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the vault contract
     * @param _owner Contract owner address
     * @param _authoritySigner Authority signer address for signature verification
     * @param _cryptoartNFT Address of the CryptoartNFT contract
     */
    function initialize(
        address _owner,
        address _authoritySigner,
        address _cryptoartNFT
    ) external initializer {
        if (
            _owner == address(0) ||
            _authoritySigner == address(0) ||
            _cryptoartNFT == address(0)
        ) {
            revert Error.Admin_ZeroAddress();
        }

        __Ownable_init(_owner);
        __Pausable_init();
        __ReentrancyGuardTransient_init();

        authoritySigner = _authoritySigner;
        cryptoartNFT = CryptoartNFT(_cryptoartNFT);
        commitFee = INITIAL_COMMIT_FEE;
        revealDelay = INITIAL_REVEAL_DELAY;
        commitTimeout = INITIAL_COMMIT_TIMEOUT;
        lockupPeriod = INITIAL_LOCKUP_PERIOD;
    }

    // ==========================================================================
    // Modifiers
    // ==========================================================================

    modifier onlyAuthoritySigner() {
        if (msg.sender != authoritySigner)
            revert Error.Auth_Unauthorized(msg.sender);
        _;
    }

    modifier onlyIfLocked(uint256 tokenId) {
        if (lockStatus[tokenId] != LockStatus.LOCKED) {
            revert Error.Vault_NotLocked(tokenId);
        }
        _;
    }

    modifier onlyAfterLockupPeriod(uint256 tokenId) {
        uint256 unlockableAt = lockTimestamps[tokenId] + lockupPeriod;
        if (block.timestamp < unlockableAt) {
            revert Error.Vault_LockupPeriodNotExpired(tokenId, unlockableAt);
        }
        _;
    }

    modifier onlyCommitter(uint256 tokenId) {
        if (msg.sender != unlockCommits[tokenId].committer) {
            revert Error.Vault_NotCommitter(msg.sender, tokenId);
        }
        _;
    }

    // ==========================================================================
    // Core Locking Functions (Used by Both Unlock Paths)
    // ==========================================================================

    /**
     * @notice Authorize a lock for an NFT (before NFT arrives in vault)
     * @dev Authority signer only. Creates authorization; NFT will be locked when deposited.
     *      This function is used for BOTH fast path and slow path unlock scenarios.
     * @param tokenId The token ID to authorize for locking
     * @param secretHash The keccak256 hash of the secret
     */
    function setLock(
        uint256 tokenId,
        bytes32 secretHash
    ) external onlyAuthoritySigner whenNotPaused {
        if (lockStatus[tokenId] != LockStatus.NONE) {
            revert Error.Vault_AlreadyLocked(tokenId);
        }

        // Set to AUTHORIZED status (waiting for NFT deposit)
        lockStatus[tokenId] = LockStatus.AUTHORIZED;
        secretHashes[tokenId] = secretHash;

        emit NFTLocked(tokenId);
    }

    /**
     * @notice Cancel an authorized lock before NFT is deposited
     * @dev Authority signer only. Can only cancel AUTHORIZED locks (not LOCKED).
     * @param tokenId The token ID to cancel authorization for
     */
    function cancelLock(uint256 tokenId) external onlyAuthoritySigner {
        if (lockStatus[tokenId] != LockStatus.AUTHORIZED) {
            revert Error.Vault_NotAuthorized(tokenId);
        }

        // Clean up state
        delete lockStatus[tokenId];
        delete secretHashes[tokenId];
        delete lockTimestamps[tokenId];

        emit LockCanceled(tokenId, msg.sender);
    }

    // ==========================================================================
    // Fast Path: Single-Transaction Unlock (Backend Required)
    // ==========================================================================

    /**
     * @notice Unlock and claim NFT with secret (fast path - requires backend signature)
     * @dev Single transaction. Backend signature binds secret to caller's wallet to prevent frontrunning.
     * @param tokenId The token ID to unlock
     * @param secret The plaintext secret (will be hashed and verified)
     * @param unlockSignature Authority signature binding (recipient + tokenId + secretHash)
     * @param deadline Signature expiration timestamp
     */
    function unlock(
        uint256 tokenId,
        bytes32 secret,
        bytes calldata unlockSignature,
        uint256 deadline
    )
        external
        whenNotPaused
        onlyIfLocked(tokenId)
        onlyAfterLockupPeriod(tokenId)
        nonReentrant
    {
        // Verify the secret matches stored secret hash
        bytes32 secretHash = keccak256(abi.encodePacked(secret));
        if (secretHash != secretHashes[tokenId]) {
            revert Error.Vault_InvalidSecret(tokenId);
        }

        // Verify unlock signature (binds secret to msg.sender wallet)
        // This prevents frontrunning: even if attacker sees secret in mempool,
        // they can't use it because signature won't validate for their address
        _validateUnlockSignature(
            tokenId,
            msg.sender,
            secretHash,
            unlockSignature,
            deadline
        );

        // Delete entries for gas refund
        delete lockStatus[tokenId];
        delete secretHashes[tokenId];
        delete lockTimestamps[tokenId];

        // Set redeemable = true
        // Vault is whitelisted, so no signature needed
        cryptoartNFT.markAsRedeemable(tokenId, "", type(uint256).max);

        cryptoartNFT.safeTransferFrom(address(this), msg.sender, tokenId);

        emit NFTUnlocked(tokenId, msg.sender);
    }

    // ==========================================================================
    // Slow Path: Commit-Reveal Unlock (Emergency Fallback, backend goes down)
    // ==========================================================================

    /**
     * @notice Commits to unlock an NFT (slow path step 1 - emergency fallback when backend down)
