// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {CryptoartNFT} from "./CryptoartNFT.sol";
import {CryptoartVault} from "./CryptoartVault.sol";
import {Error} from "./libraries/Error.sol";
import {ReentrancyGuardTransientUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardTransientUpgradeable.sol";

/**
 * @title CryptoartInventoryVault
 * @notice Simple inventory vault for Cryptoart-owned pre-minted NFTs
 * @dev Holds NFTs until order fulfillment, then transfers them to CryptoartVault.
 *      Authority signer can only send NFTs to CryptoartVault (not arbitrary addresses).
 *      Owner (ledger address) can withdraw NFTs to any address.
 */
contract CryptoartInventoryVault is
    OwnableUpgradeable,
    PausableUpgradeable,
    IERC721Receiver,
    ReentrancyGuardTransientUpgradeable
{
    // ==========================================================================
    // State Variables
    // ==========================================================================

    uint256 private constant MAX_BATCH_SIZE = 50;
    address public authoritySigner;
    CryptoartNFT public cryptoartNFT;
    CryptoartVault public cryptoartVault;

    // Variable gap in case new variables are added on subsequent upgrades
    uint256[50] private __gap;

    // ==========================================================================
    // Events
    // ==========================================================================

    event NFTDeposited(
        uint256 indexed tokenId,
        address indexed from,
        address indexed operator
    );
    event NFTTransferredToVault(
        uint256 indexed tokenId,
        address indexed triggeredBy
    );
    event NFTWithdrawn(
        uint256 indexed tokenId,
        address indexed recipient,
        address indexed triggeredBy
    );
    event AuthoritySignerUpdated(
        address indexed oldSigner,
        address indexed newSigner
    );

    // ==========================================================================
    // Initialization
    // ==========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the inventory vault contract
     * @param _owner Contract owner (ledger address) - can withdraw NFTs to any address
     * @param _authoritySigner Authority signer - can transfer NFTs to CryptoartVault only
     * @param _cryptoartNFT Address of the CryptoartNFT contract
     * @param _cryptoartVault Address of the CryptoartVault contract
     */
    function initialize(
        address _owner,
        address _authoritySigner,
        address _cryptoartNFT,
        address _cryptoartVault
    ) external initializer {
        if (
            _owner == address(0) ||
            _authoritySigner == address(0) ||
            _cryptoartNFT == address(0) ||
            _cryptoartVault == address(0)
        ) {
            revert Error.Admin_ZeroAddress();
        }

        __Ownable_init(_owner);
        __Pausable_init();
        __ReentrancyGuardTransient_init();

        authoritySigner = _authoritySigner;
        cryptoartNFT = CryptoartNFT(_cryptoartNFT);
        cryptoartVault = CryptoartVault(_cryptoartVault);
    }

    // ==========================================================================
    // Modifiers
    // ==========================================================================

    modifier onlyAuthoritySigner() {
        if (msg.sender != authoritySigner)
            revert Error.Auth_Unauthorized(msg.sender);
        _;
    }

    // ==========================================================================
    // Core Operations
    // ==========================================================================

    /**
     * @notice Transfer an NFT from inventory to CryptoartVault
     * @dev Authority signer only. CryptoartVault's gatekeeper will validate
     *      that setLock was called and the NFT is from CryptoartNFT.
     * @param tokenId The token ID to transfer
     */
    function transferToVault(
        uint256 tokenId
    ) external onlyAuthoritySigner whenNotPaused nonReentrant {
        (uint256 index, , ) = cryptoartNFT.tokenURIs(tokenId);
        if (index != 1) {
          revert Error.Vault_NFTMustNotBeRedeemable(tokenId, index);
        }

        cryptoartNFT.safeTransferFrom(
            address(this),
            address(cryptoartVault),
            tokenId
        );

        emit NFTTransferredToVault(tokenId, msg.sender);
    }

    /**
     * @notice Transfer multiple NFTs from inventory to CryptoartVault
     * @dev Authority signer only. CryptoartVault's gatekeeper will validate
     *      that setLock was called and the NFT is from CryptoartNFT.
     * @param tokenIds The token IDs to transfer
     */
    function batchTransferToVault(
        uint256[] calldata tokenIds
    ) external onlyAuthoritySigner whenNotPaused nonReentrant {
        uint256 length = tokenIds.length;
        if (length == 0) revert Error.Batch_EmptyArray();
        if (length > MAX_BATCH_SIZE) {
            revert Error.Batch_MaxSizeExceeded(length, MAX_BATCH_SIZE);
        }

        for (uint256 i = 0; i < length; i++) {
            cryptoartNFT.safeTransferFrom(
                address(this),
                address(cryptoartVault),
                tokenIds[i]
            );

            emit NFTTransferredToVault(tokenIds[i], msg.sender);
        }
    }

    /**
     * @notice Withdraw an NFT from inventory to any address
     * @dev Owner only. For order cancellations, returns, or manual management.
     * @param tokenId The token ID to withdraw
     * @param recipient The address to receive the NFT
     */
    function withdraw(
        uint256 tokenId,
        address recipient
    ) external onlyOwner nonReentrant {
        if (recipient == address(0)) {
            revert Error.Admin_ZeroAddress();
        }
        cryptoartNFT.safeTransferFrom(address(this), recipient, tokenId);

        emit NFTWithdrawn(tokenId, recipient, msg.sender);
    }

    /**
     * @notice Withdraw multiple NFTs from inventory to any address
     * @dev Owner only. For order cancellations, returns, or manual management.
     * @param tokenIds The token IDs to withdraw
     * @param recipient The address to receive the NFTs
     */
    function batchWithdraw(
        uint256[] calldata tokenIds,
        address recipient
    ) external onlyOwner nonReentrant {
        if (recipient == address(0)) {
            revert Error.Admin_ZeroAddress();
        }
        uint256 length = tokenIds.length;
        if (length == 0) revert Error.Batch_EmptyArray();
        if (length > MAX_BATCH_SIZE) {
            revert Error.Batch_MaxSizeExceeded(length, MAX_BATCH_SIZE);
        }

        for (uint256 i = 0; i < length; i++) {
            cryptoartNFT.safeTransferFrom(
                address(this),
                recipient,
                tokenIds[i]
            );
            emit NFTWithdrawn(tokenIds[i], recipient, msg.sender);
        }
    }

    // ==========================================================================
    // Admin Functions
    // ==========================================================================

    /**
     * @notice Update authority signer address
     * @param newSigner New authority signer address
     */
    function updateAuthoritySigner(address newSigner) external onlyOwner {
        if (newSigner == address(0)) {
            revert Error.Admin_ZeroAddress();
        }
        address oldSigner = authoritySigner;
        authoritySigner = newSigner;
        emit AuthoritySignerUpdated(oldSigner, newSigner);
    }

    /**
     * @notice Pause the contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause the contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ==========================================================================
    // ERC-721 Receiver (Gatekeeper)
    // ==========================================================================

    /**
     * @notice Handle incoming NFTs - acts as gatekeeper
     * @dev Only accepts NFTs from CryptoartNFT contract
     * @param operator The address that initiated the transfer (who called safeTransferFrom)
     * @param from The address that previously owned the token
     * @param tokenId The token ID being transferred
     * @return bytes4 The selector to confirm acceptance
     */
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata
    ) external override whenNotPaused returns (bytes4) {
        // Only accept NFTs from CryptoartNFT contract
        if (msg.sender != address(cryptoartNFT)) {
            revert Error.InventoryVault_InvalidNFTContract(tokenId, msg.sender);
        }

        emit NFTDeposited(tokenId, from, operator);

        return this.onERC721Received.selector;
    }
}
